        ("納豆は体にいいと言われています。", "Nattou wa karada ni ii to iwarete imasu.", "Natto dikatakan baik untuk tubuh."),
        ("この本は難しいと言われています。", "Kono hon wa muzukashii to iwarete imasu.", "Buku ini dikatakan sulit."),
