        ("話し合いの結果、決定しました。", "Hanashiai no kekka, kettei shimashita.", "Sebagai hasil diskusi, sudah diputuskan."),
        ("検査の結果、異常はありませんでした。", "Kensa no kekka, ijou wa arimasen deshita.", "Sebagai hasil pemeriksaan, tidak ada kelainan."),
