        ("結局、彼が正しかったです。", "Kekkyoku, kare ga tadashikatta desu.", "Pada akhirnya, dia yang benar."),
        ("結局どうなりましたか。", "Kekkyoku dou narimashita ka.", "Pada akhirnya bagaimana hasilnya?"),
