        ("子供にとって、遊びは大切です。", "Kodomo ni totte, asobi wa taisetsu desu.", "Bagi anak-anak, bermain itu penting."),
        ("この会社にとって、大きな挑戦です。", "Kono kaisha ni totte, ooki na chousen desu.", "Bagi perusahaan ini, ini tantangan besar."),
