        ("彼はアメリカ育ちだから、英語が上手なわけです。", "Kare wa Amerika sodachi dakara, eigo ga jouzu na wake desu.", "Dia dibesarkan di Amerika, jadi pantas saja mahir bahasa Inggris."),
        ("なるほど、そういうわけですか。", "Naruhodo, sou iu wake desu ka.", "Oh begitu, jadi begitu ceritanya."),
