        ("恐らくこれが原因でしょう。", "Osoraku kore ga gen'in deshou.", "Mungkin inilah penyebabnya."),
        ("恐らく明日は晴れると思います。", "Osoraku ashita wa hareru to omoimasu.", "Saya rasa kemungkinan besar besok akan cerah."),
