        ("彼はろくに勉強しないで、試験を受けた。", "Kare wa roku ni benkyou shinaide, shiken o uketa.", "Dia mengikuti ujian tanpa belajar dengan layak."),
        ("ろくに話も聞かずに、決めつけないでください。", "Roku ni hanashi mo kikazu ni, kimetsukenaide kudasai.", "Jangan main menyimpulkan tanpa mendengarkan dengan benar."),
