        ("驚くには当たらない結果だった。", "Odoroku niwa ataranai kekka datta.", "Itu hasil yang tidak perlu sampai membuat terkejut."),
        ("感謝するには当たらない、当然のことをしただけだ。", "Kansha suru niwa ataranai, touzen no koto o shita dake da.", "Tidak perlu sampai berterima kasih, saya hanya melakukan hal yang sewajarnya."),
