def build_n1_entries():
    entries = []
    for suffix, pattern, romaji, meaning, formation, usage_notes, similar, sentence_examples in N1_GRAMMAR_ENTRIES:
        entries.append({
            "id": f"bunpou_{suffix}",
            "pattern": pattern,
            "patternRomaji": romaji,
            "jlptLevel": "N1",
            "meaning": meaning,
            "formation": formation,
            "usageNotes": usage_notes,
            "similarPatterns": [f"bunpou_{s}" for s in similar],
            "sentenceExamples": [
                {"japanese": jp, "romaji": ro, "translation": tr}
                for jp, ro, tr in sentence_examples
            ],
        })
    return entries


def build_placeholder_entries():
    entries = []
    for level, count in PLACEHOLDER_COUNTS.items():
        for i in range(1, count + 1):
            entries.append({
                "id": f"bunpou_{level.lower()}_placeholder_{i}",
                "pattern": "",
                "patternRomaji": "",
                "jlptLevel": level,
                "meaning": "",
                "formation": "",
                "usageNotes": "",
                "similarPatterns": [],
                "sentenceExamples": [],
                "placeholder": True,
            })
    return entries


def main():
    data = (
        build_n5_entries() + build_n4_entries() + build_n3_entries()
        + build_n2_entries() + build_n1_entries() + build_placeholder_entries()
    )
    with open("assets/data/bunpou_data.json", "w", encoding="utf-8") as f:
        json.dump(data, f, ensure_ascii=False, indent=2)

    # Emit _levels.json from the data we just wrote, rather than leaving
    # it hand-maintained. It had silently drifted: it claimed 84 N5
    # patterns while the dataset held 89, so the Bunpou home screen was
    # showing a stale count. Every other module with a `_levels.json`
    # (kanji, kaiwa, dokkai) already generates it; this one did not, which
    # is the same generated-vs-hand-edited drift CLAUDE.md documents for
    # Kotoba's `_categories.json`.
    counts = {}
    for e in data:
        counts[e["jlptLevel"]] = counts.get(e["jlptLevel"], 0) + 1
    levels = [
        {"id": lv, "name": lv, "available": True, "bunpouCount": counts.get(lv, 0)}
        for lv in ("N5", "N4", "N3", "N2", "N1")
    ]
    with open("assets/data/bunpou/_levels.json", "w", encoding="utf-8") as f:
        json.dump(levels, f, ensure_ascii=False, indent=2)

    print(f"Wrote {len(data)} bunpou entries ({len(N5_GRAMMAR_ENTRIES)} real N5 (of "
          f"{len(N5_GRAMMAR)} locked) + {len(N4_GRAMMAR_ENTRIES)} real N4 (of "
          f"{len(N4_GRAMMAR)} locked) + {len(N3_GRAMMAR_ENTRIES)} real N3 (of "
          f"{len(N3_GRAMMAR)} locked) + {len(N2_GRAMMAR_ENTRIES)} real N2 (of "
          f"{len(N2_GRAMMAR)} locked) + {len(N1_GRAMMAR_ENTRIES)} real N1 (of "
          f"{len(N1_GRAMMAR)} locked) + {sum(PLACEHOLDER_COUNTS.values())} placeholders).")


if __name__ == "__main__":
    main()
